import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Tasarımcılar WebP'yi PNG'ye çevirir, çünkü düzenleme araçları PNG'yi sever. WebP web içindir; PNG ise çalışma dosyasıdır.</p>\n<p>Bir siteden indirdiğiniz görsel WebP olabilir ama Photoshop, Figma ya da eski bir düzenleme programı onu açmayabilir. PNG'ye dönüştürmek bu engeli kaldırır.</p>\n<p>Bu yazı, tasarımcıların neden dönüştürdüğünü, saydamlığın nasıl korunduğunu ve hangi programda hangi formatın işe yaradığını anlatıyor.</p>\n<h2 id=\"why-designers-convert\">Tasarımcılar WebP'yi neden PNG'ye dönüştürür?</h2>\n<p>Tasarımcılar, araçları WebP'yi açmadığı için dönüştürür. Eski Photoshop sürümleri ve birçok eklenti yalnızca JPG ve PNG bekler.</p>\n<p>Bir başka neden tutarlılıktır. Projedeki tüm kaynaklar PNG ise ekip neyle çalıştığını bilir; karışık formatlar hata çıkarır.</p>\n<p>Üçüncü neden teslimattır. Müşteriye gönderilen dosya her programda açılmalıdır; PNG bu garantiyi verir.</p>\n<h2 id=\"editing-workflow\">PNG üzerine kurulu bir düzenleme akışı</h2>\n<p>İyi bir akış şöyle işler: WebP kaynağı indirilir, PNG'ye dönüştürülür, düzenlenir ve istenen formatta kaydedilir.</p>\n<p>Orijinal WebP ayrı bir klasörde saklanır. Düzenlenmiş sürüm ayrı bir dosyadır; orijinal, ileride yeniden başlamak için gerekir.</p>\n<p>Düzenleme sırasında PNG kullanın. Kayıpsız olduğu için tekrar tekrar kaydetmek kalite kaybettirmez.</p>\n<h2 id=\"transparency-for-designers\">Tasarımcıların güvendiği saydamlık</h2>\n<p>Logolar ve simgeler saydamlığa dayanır. Saydam arka planlı bir WebP, PNG olarak da saydam kalır; bu, tasarımın temelidir.</p>\n<p>Dönüştürme bitince saydamlığı kontrol edin. Önizlemede saydam alanlar damalı desenle görünür; köşeler temiz olmalıdır.</p>\n<p>Yumuşak kenarlar ve gölgeler de korunur. Kısmi saydamlık iki formatta da aynı işler; tasarımda sürpriz yaşanmaz.</p>\n<h2 id=\"compatibility-map\">PNG için uyumluluk haritası</h2>\n<p>Photoshop, Figma, Illustrator ve GIMP PNG'yi sorunsuz açar. WebP desteği ise sürüme göre değişir.</p>\n<p>Word ve PowerPoint PNG'yi her sürümde açar. WebP yalnızca güncel sürümlerde çalışır; eski sürümlerde açılmaz.</p>\n<p>E-posta istemcileri ve baskı merkezleri PNG'yi kabul eder. WebP bu alanlarda hâlâ güvenilmezdir.</p>\n<h2 id=\"when-png-wins\">PNG'nin WebP'yi yendiği durumlar</h2>\n<p>Düzenleme söz konusuysa PNG kazanır. Kayıpsız yapı ve evrensel destek, çalışma dosyası için idealdir.</p>\n<p>Paylaşım söz konusuysa PNG kazanır. Alıcının programı bilinmiyorsa PNG her zaman açılır.</p>\n<p>Arşiv söz konusuysa PNG kazanır. Otuz yıllık destek, dosyanın on yıl sonra da açılacağını garantiler.</p>\n<h2 id=\"when-webp-wins\">WebP'nin PNG'yi yendiği durumlar</h2>\n<p>Web söz konusuysa WebP kazanır. Daha küçük dosyalar sayfaları hızlandırır ve ziyaretçiler farkı hisseder.</p>\n<p>Çok sayıda görsel varsa WebP kazanır. Onlarca görselin toplam kazancı, sayfa hızını belirgin iyileştirir.</p>\n<p>Depolama sınırlıysa WebP kazanır. Aynı arşiv WebP olarak çok daha az yer kaplar.</p>\n<h2 id=\"file-size-reality\">Dosya boyutunun gerçeği</h2>\n<p>PNG, WebP'den her zaman daha büyüktür. Aynı görsel PNG olarak iki ya da üç kat büyük olabilir.</p>\n<p>Bu fark çalışma dosyalarında sorun değildir. Düzenleme sırasında boyut önemli değildir; önemli olan kalite ve uyumluluktur.</p>\n<p>Teslimatta boyut yeniden önemli olur. Web için WebP, baskı için PNG kullanın; her hedef kendi formatını alır.</p>\n<h2 id=\"colour-and-profiles\">Dönüştürmede renk ve profiller</h2>\n<p>Renk profilleri genelde korunur. Görselin renkleri dönüştürmeden sonra da aynı görünür.</p>\n<p>Marka renkleri kritikse karşılaştırın. Dönüştürülen PNG'yi orijinal WebP ile yan yana açıp renklerin aynı olduğunu kontrol edin.</p>\n<p>Geniş renk gamlı görsellerde dikkatli olun. Bazı profiller dönüşümde kaybolabilir; şüphede kalırsanız orijinali koruyun.</p>\n<h2 id=\"team-workflows\">Dönüştürme etrafında ekip akışları</h2>\n<p>Ekipte kural net olmalıdır: kaynaklar WebP, çalışma dosyaları PNG. Herkes aynı kuralı izlerse karışıklık olmaz.</p>\n<p>Dönüştürülen dosyaları paylaşılan klasöre koyun. Orijinaller ayrı kalır; ekip dönüştürülenlerle çalışır.</p>\n<p>Kuralı proje notlarına yazın. Yeni katılan biri, format seçimini tahmin etmek zorunda kalmaz.</p>\n<h2 id=\"common-mistakes\">Kaçınılması gereken yaygın hatalar</h2>\n<p>En yaygın hata, PNG'nin kaliteyi artıracağını sanmaktır. PNG yalnızca mevcut pikselleri korur; kaybolan ayrıntıyı geri getirmez.</p>\n<p>Bir başka hata, orijinal WebP'yi silmektir. PNG büyüdüğü için arşivde WebP'yi saklamak daha akıllıcadır.</p>\n<p>Üçüncü hata, animasyonlu WebP'yi PNG'ye çevirip animasyon beklemektir. PNG hareketsizdir; yalnızca ilk kare kalır.</p>\n<h2 id=\"decision-guide\">Tasarımcılar için karar kılavuzu</h2>\n<p>Düzenleyecek misiniz? PNG'ye dönüştürün. Programınız WebP açsa bile, PNG daha güvenli çalışma dosyasıdır.</p>\n<p>Web'de yayınlayacak mısınız? WebP'yi koruyun. Hız kazancı gerçektir ve ziyaretçiler farkı hisseder.</p>\n<p>Müşteriye gönderecek misiniz? PNG verin. Müşterinin programı ne olursa olsun, dosya açılır.</p>\n<h2 id=\"png-in-video-editing\">Video düzenlemede PNG</h2>\n<p>Video düzenleme programları PNG'yi küçük resim ve bindirme olarak kabul eder. WebP bu programlarda genellikle desteklenmez.</p>\n<p>Logo bindirmeleri için PNG kullanın. Saydamlık korunur ve logo videonun üzerinde temiz görünür.</p>\n<p>Kapak görselleri için de PNG güvenlidir. Program ne olursa olsun, dosya açılır.</p>\n<h2 id=\"png-in-3d-games\">3B ve oyun kaynaklarında PNG</h2>\n<p>Oyun motorları PNG dokularını standart olarak kabul eder. WebP desteği motordan motora değişir.</p>\n<p>Şeffaf dokular için PNG kullanın. Alfa kanalı oyun motorlarında güvenilir biçimde işlenir.</p>\n<p>Kaynakları PNG olarak saklayın. Motorun istediği formata derleme sırasında dönüştürebilirsiniz.</p>\n<h2 id=\"png-in-email-signatures\">E-posta imzalarında PNG</h2>\n<p>E-posta imzalarındaki logolar PNG olmalıdır. Tüm istemciler PNG'yi gösterir; WebP bazı istemcilerde kırık görünür.</p>\n<p>İmza görseli küçük olmalıdır. PNG'yi boyutlandırmadan önce sıkıştırın; imza e-postayı ağırlaştırmamalıdır.</p>\n<p>İmzayı farklı istemcilerde test edin. Logo her yerde aynı görünmelidir.</p>\n<h2 id=\"png-in-documentation\">Belgelerde PNG</h2>\n<p>Belge ve kılavuzlardaki ekran görüntüleri PNG olmalıdır. Kayıpsız yapı, yazıları keskin tutar.</p>\n<p>Belgeler yıllarca saklanır. PNG'nin evrensel desteği, belgenin gelecekte de açılacağını garantiler.</p>\n<p>PDF'ye çevirirken PNG kullanın. Görseller PDF içinde keskin kalır.</p>\n<h2 id=\"png-in-legal-medical\">Hukuki ve tıbbi görsellerde PNG</h2>\n<p>Hukuki ve tıbbi görsellerde kayıpsız format zorunludur. PNG, ayrıntıyı bozmadan saklar.</p>\n<p>WebP'nin kayıplı sıkıştırması, kritik ayrıntıyı silebilir. Bu alanlarda risk almayın; PNG kullanın.</p>\n<p>Arşiv için de PNG kullanın. Yıllar sonra açılacağından emin olmalısınız.</p>\n<h2 id=\"png-in-presentations\">Sunumlarda PNG</h2>\n<p>Sunumlarda PNG kullanın. Salonun bilgisayarı eski olabilir; PNG her makinede açılır.</p>\n<p>Görselleri slayda eklemeden önce PNG'ye çevirin. Sunum günü sürpriz yaşanmaz.</p>\n<p>Sunumu paylaşmadan önce dosyaları test edin. Görsellerin açıldığından emin olun.</p>\n<p>Özetle: düzenleme için PNG, yayın için WebP. Dönüştürmek için <a href=\"/tr/webp-png-ye-donustur\">WebP'den PNG'ye aracını</a> açın; adımlar için <a href=\"/tr/blog/webp-png-ye-nasil-donusturulur\">WebP PNG'ye nasıl dönüştürülür</a> yazısına bakın. Kılavuzun tamamı <a href=\"/tr/blog/webp-png-ye-donustur-rehberi\">WebP'den PNG'ye kılavuzunda</a>; ters yön için <a href=\"/tr/png-webp-ye-donustur\">PNG'den WebP'ye dönüştürücü</a> hazırdır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Tasarımcılar düzenleme yapmadan önce WebP'yi neden PNG'ye dönüştürür?","answer":"Çünkü düzenleme araçları PNG'yi sever. Eski Photoshop sürümleri ve birçok eklenti WebP açamaz; PNG ise her programda sorunsuz çalışır. Ayrıca PNG kayıpsızdır, bu yüzden tekrar tekrar kaydetmek kalite kaybettirmez."},{"question":"WebP'yi PNG'ye dönüştürmek görsel kalitesini tam olarak korur mu?","answer":"Evet, dönüştürmenin kendisi kayıpsızdır; pikseller birebir aktarılır. Ancak kayıplı bir WebP zaten sıkıştırma sırasında ayrıntı kaybetmiştir; PNG'ye çevirmek o ayrıntıyı geri getirmez. Sonuç, kaynak WebP ile piksel piksel aynıdır."},{"question":"Dönüştürülen PNG'leri Photoshop ve Figma'da kullanabilir miyim?","answer":"Evet. Photoshop, Figma, Illustrator ve GIMP PNG'yi sorunsuz açar. Saydamlık korunduğu için logolar ve simgeler her arka plan üzerinde temiz görünür. WebP desteği sürüme göre değişirken PNG her sürümde çalışır."},{"question":"Bir tasarımcı neden WebP yerine PNG'ye ihtiyaç duyar?","answer":"Düzenleme, paylaşım ve arşiv için. Programı bilinmeyen bir alıcıya dosya gönderirken, eski bir yazılımla çalışırken ya da kayıpsız bir çalışma dosyası gerekirken PNG doğru seçimdir. WebP yalnızca web yayını için üstündür."},{"question":"WebP dosyası bozuksa ya da gerçek bir WebP değilse ne olur?","answer":"Araç dosyayı açamaz ve hata gösterir. Önce dosyanın gerçekten WebP olduğundan emin olun; uzantıyı kontrol edin ve dosyayı tarayıcıda açmayı deneyin. Bozuk dosyayı yeniden indirmeniz gerekebilir."},{"question":"Web görsel kitaplığımın tamamını PNG'ye dönüştürmeli miyim?","answer":"Hayır. Yalnızca düzenleyeceğiniz ya da paylaşacağınız dosyaları dönüştürün. Web'de kalacak görseller WebP olarak kalsın; PNG arşivde çok yer kaplar. Kural basit: çalışma dosyası PNG, yayın dosyası WebP."}];
